import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/introduction.md","filePath":"ja/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`ja/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to “はじめに”">​</a></h1><h2 id="sudoku-について" tabindex="-1">Sudoku について <a class="header-anchor" href="#sudoku-について" aria-label="Permalink to “Sudoku について”">​</a></h2><p><strong>Sudoku — 定番の数字パズルを、完璧な仕上がりで。</strong></p><p><img src="/screenshot-ipad-main.png" alt="iPad で動作する Sudoku"></p><p>長年愛されてきた論理パズルを、滑らかな操作、美しいテーマ、そして飽きのこない遊び心地で現代のデバイス向けに磨き上げました。初めてプレイする方も、熟練のベテランも、待ち望んでいた数独体験がここにあります。</p><h2 id="主な機能" tabindex="-1">主な機能 <a class="header-anchor" href="#主な機能" aria-label="Permalink to “主な機能”">​</a></h2><h3 id="🔢-本格的なゲームプレイ" tabindex="-1">🔢 <strong>本格的なゲームプレイ</strong> <a class="header-anchor" href="#🔢-本格的なゲームプレイ" aria-label="Permalink to “🔢 本格的なゲームプレイ”">​</a></h3><p>定番ルールに忠実 — 9×9 のグリッドを、各行・各列・各 3×3 ボックスに 1 から 9 の数字がちょうど 1 回ずつ入るように埋めます。タップして数字を置き、候補には鉛筆メモを使い、論理の力だけで解答へ導きましょう。</p><h3 id="🎯-5-段階の難易度" tabindex="-1">🎯 <strong>5 段階の難易度</strong> <a class="header-anchor" href="#🎯-5-段階の難易度" aria-label="Permalink to “🎯 5 段階の難易度”">​</a></h3><p>初期配置マスの数が異なる、綿密に調整された 5 つの難易度をご用意しています：</p><table tabindex="0"><thead><tr><th>レベル</th><th>初期配置マス</th><th>説明</th></tr></thead><tbody><tr><td>やさしい</td><td>45</td><td>初心者や短時間のプレイに最適</td></tr><tr><td>ふつう</td><td>36</td><td>気軽に遊ぶ方にちょうどよい手応え</td></tr><tr><td>むずかしい</td><td>31</td><td>論理的な推論テクニックが必要</td></tr><tr><td>エキスパート</td><td>27</td><td>本格的な挑戦を求める経験者向け</td></tr><tr><td>マスター</td><td>24</td><td>究極の挑戦 — 勇気ある方だけに</td></tr></tbody></table><p>各パズルはユニークに生成されるため、同じ問題が二度出ることはありません。</p><h3 id="📱-ユニバーサルアプリ" tabindex="-1">📱 <strong>ユニバーサルアプリ</strong> <a class="header-anchor" href="#📱-ユニバーサルアプリ" aria-label="Permalink to “📱 ユニバーサルアプリ”">​</a></h3><p>1 回の購入で iPhone、iPad、Mac のすべてで使えます。各プラットフォームに合わせたネイティブ操作 — iOS ではタッチジェスチャー、Mac ではマウスとキーボード。進行状況は iCloud を通じてすべてのデバイスで同期されます。</p><p><img src="/screenshot-iphone-main.png" alt="iPhone で動作する Sudoku"></p><p><img src="/screenshot-mac-difficulty.png" alt="Mac で動作する Sudoku"></p><h3 id="💡-ヒント-鉛筆メモ" tabindex="-1">💡 <strong>ヒント＆鉛筆メモ</strong> <a class="header-anchor" href="#💡-ヒント-鉛筆メモ" aria-label="Permalink to “💡 ヒント＆鉛筆メモ”">​</a></h3><ul><li><strong>ヒント</strong>：行き詰まったら？ パズル全体を台無しにせず、正しいマスを 1 つだけ明かすヒントを利用できます。</li><li><strong>鉛筆（メモ）</strong>：鉛筆モードに切り替えると、空のマスに候補の数字を書き込めます。数字を置くと、同じ行・列・ボックスにある候補の鉛筆メモは自動的に消去されます。</li><li><strong>誤りチェック</strong>：誤った入力のマスを任意で強調表示できるので、間違いから学べます。</li><li><strong>元に戻す</strong>：完全なアンドゥ機能 — いつでもどの手でも取り消せます。</li></ul><h3 id="🏆-デイリーチャレンジ" tabindex="-1">🏆 <strong>デイリーチャレンジ</strong> <a class="header-anchor" href="#🏆-デイリーチャレンジ" aria-label="Permalink to “🏆 デイリーチャレンジ”">​</a></h3><p>毎日、マスター難易度の新しいパズルが登場します。連続記録を伸ばし、統計のカレンダー表示で毎日の進み具合を確認しましょう。</p><h3 id="📊-統計" tabindex="-1">📊 <strong>統計</strong> <a class="header-anchor" href="#📊-統計" aria-label="Permalink to “📊 統計”">​</a></h3><p>成績を記録できます：総プレイ数、勝率、現在の連続記録、最高連続記録、さらに難易度ごとのベストタイムや平均タイムなどの内訳。iCloud で同期されます。</p><h3 id="🎨-8-種類の美しいテーマ" tabindex="-1">🎨 <strong>8 種類の美しいテーマ</strong> <a class="header-anchor" href="#🎨-8-種類の美しいテーマ" aria-label="Permalink to “🎨 8 種類の美しいテーマ”">​</a></h3><p>8 つの手作りカラーテーマでボードを自分好みに：クラシック、ミッドナイト、ペーパー、フォレスト、オーシャン、サンセット、ラベンダー、ローズ。どのテーマも優れた読みやすさを保ちながら、それぞれ異なる視覚体験を提供します。</p><h3 id="☁️-icloud-同期" tabindex="-1">☁️ <strong>iCloud 同期</strong> <a class="header-anchor" href="#☁️-icloud-同期" aria-label="Permalink to “☁️ iCloud 同期”">​</a></h3><p>設定、統計、ゲームのセーブデータ、デイリーチャレンジの進捗は、CloudKit を通じてすべての Apple デバイス間で自動的に同期されます。iPhone で始めたゲームを、Mac で続きから遊べます。</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>ベストクリアタイムでリーダーボードを競い、実績を獲得できます：First Solve、Easy Clear、Medium Clear、Hard Clear、Expert Clear、Master Clear、そして Flawless（ヒントも誤りもなしでクリア）。</p><h3 id="🔇-クリーンで広告なし" tabindex="-1">🔇 <strong>クリーンで広告なし</strong> <a class="header-anchor" href="#🔇-クリーンで広告なし" aria-label="Permalink to “🔇 クリーンで広告なし”">​</a></h3><p>中断もポップアップも広告も App 内課金もありません。純粋にパズルだけに集中できます。</p><h3 id="🌍-25-言語" tabindex="-1">🌍 <strong>25 言語</strong> <a class="header-anchor" href="#🌍-25-言語" aria-label="Permalink to “🌍 25 言語”">​</a></h3><p>アプリを再起動することなく、設定から実行中に言語を切り替えられます。英語、中国語（簡体字・繁体字）、日本語、韓国語、フランス語、ドイツ語、スペイン語、イタリア語、ロシア語、ポルトガル語、オランダ語、ベトナム語、タイ語、ヒンディー語、トルコ語、ギリシャ語、フィンランド語、ノルウェー語、デンマーク語、ハンガリー語、インドネシア語、マレー語、ウクライナ語、ドイツ語（スイス）に対応しています。</p><h3 id="🔊-効果音" tabindex="-1">🔊 <strong>効果音</strong> <a class="header-anchor" href="#🔊-効果音" aria-label="Permalink to “🔊 効果音”">​</a></h3><p>数字の配置、ヒント、誤り、勝利には控えめな効果音が付きます — 設定でオン／オフを切り替えられます。</p><h3 id="🖨️-パズルの印刷" tabindex="-1">🖨️ <strong>パズルの印刷</strong> <a class="header-anchor" href="#🖨️-パズルの印刷" aria-label="Permalink to “🖨️ パズルの印刷”">​</a></h3><p>Mac アプリからは、難易度を選び、解答も任意で含めてパズルを直接印刷できます。ペンと紙でオフラインに解くのに最適です。</p><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to “システム要件”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 以降</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）以降（Apple Silicon）</li><li><strong>ストレージ</strong>：約 50 MB</li></ul><h2 id="プライバシー" tabindex="-1">プライバシー <a class="header-anchor" href="#プライバシー" aria-label="Permalink to “プライバシー”">​</a></h2><p>Sudoku は基本的なゲームプレイにおいてオフラインファーストです。すべてのゲームデータはデバイス内に保存され、ご自身の iCloud アカウントにのみ同期されます。広告も分析もサードパーティのトラッキングもありません。ネットワークを使う機能は iCloud 同期、Game Center、そして設定にある任意の「More Apps」セクションだけです。</p><p>詳細は<a href="/ja/guide/privacy.html">プライバシーポリシー</a>をご覧ください。</p><h2 id="最初のステップ" tabindex="-1">最初のステップ <a class="header-anchor" href="#最初のステップ" aria-label="Permalink to “最初のステップ”">​</a></h2><p>Sudoku が初めての方は、<a href="/ja/guide/installation.html">インストールガイド</a>から始めて、お使いのデバイスにアプリを導入してください。</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};